package com.savewhy.app;
import android.app.Dialog;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.widget.EditText;
import com.google.android.material.chip.*;
import java.io.*;
import java.util.*;
import java.util.zip.*;
import org.json.JSONObject;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import org.robolectric.android.controller.ActivityController;
import org.robolectric.shadows.ShadowDialog;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class LocalMediaTest {
    private ActivityController<MainActivity> controller;
    @Before public void language(){androidx.appcompat.app.AppCompatDelegate.setApplicationLocales(androidx.core.os.LocaleListCompat.forLanguageTags("tr"));}
    @After public void close(){if(controller!=null)controller.pause().stop().destroy();}
    private byte[] photo(){Bitmap b=Bitmap.createBitmap(1080,1920,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();return out.toByteArray();}
    private void register(Uri uri,byte[] bytes){org.robolectric.Shadows.shadowOf(RuntimeEnvironment.getApplication().getContentResolver()).registerInputStreamSupplier(uri,()->new ByteArrayInputStream(bytes));}
    private void await(java.util.function.BooleanSupplier ready)throws Exception{long end=System.currentTimeMillis()+5000;while(!ready.getAsBoolean()&&System.currentTimeMillis()<end){Thread.sleep(20);org.robolectric.Shadows.shadowOf(Looper.getMainLooper()).idle();}assertTrue(ready.getAsBoolean());}
    private Card reference(String id,Uri uri)throws Exception{Card c=new Card(id,"","Local photo","Al","Later",10,false,Collections.emptyList(),"",LocalMedia.identity(uri),Collections.singletonList("Shopping"),"headphones","ready");c.setMediaReference(uri.toString(),"Screenshot.png");return c;}
    @Test public void persistentReferenceReadsOriginalWithoutCreatingCopy()throws Exception{Uri uri=Uri.parse("content://com.example.files/documents/photo");register(uri,photo());LocalMedia media=new LocalMedia(RuntimeEnvironment.getApplication());assertTrue(media.persist(uri));assertTrue(media.accessible(uri));Bitmap bitmap=media.bitmap(uri,false,320);assertTrue(bitmap.getWidth()<=320&&bitmap.getHeight()<=320);bitmap.recycle();assertFalse(new ImageStore(RuntimeEnvironment.getApplication()).exists(LocalMedia.identity(uri)));assertTrue(RuntimeEnvironment.getApplication().getContentResolver().getPersistedUriPermissions().stream().anyMatch(p->p.getUri().equals(uri)&&p.isReadPermission()));}
    @Test public void referenceBackupCarriesMetadataAndNoOriginalFile()throws Exception{Uri uri=Uri.parse("content://com.example.files/documents/photo");Card c=reference("ref",uri);ImageStore images=new ImageStore(RuntimeEnvironment.getApplication());ByteArrayOutputStream out=new ByteArrayOutputStream();MediaBackup.write(out,CardCodec.encode(Collections.singletonList(c)),Collections.singletonList(c),images,new File(RuntimeEnvironment.getApplication().getFilesDir(),"previews"));List<String> entries=new ArrayList<>();try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(out.toByteArray()))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){entries.add(entry.getName());zip.closeEntry();}}assertEquals(Collections.singletonList("records.json"),entries);try(MediaBackup.Pending pending=MediaBackup.read(new ByteArrayInputStream(out.toByteArray()),RuntimeEnvironment.getApplication().getCacheDir(),images)){assertEquals(uri.toString(),pending.cards.get(0).mediaUri());assertEquals(c.tags,pending.cards.get(0).tags);assertTrue(pending.assets.isEmpty());}try(MediaBackup.Pending pending=MediaBackup.read(new ByteArrayInputStream(CardCodec.encode(Collections.singletonList(c)).getBytes("UTF-8")),RuntimeEnvironment.getApplication().getCacheDir(),images)){assertTrue(pending.cards.get(0).isReference());}}
    @Test public void invalidReferencesFailAndCopyMergePreserveValidReferences()throws Exception{Uri uri=Uri.parse("content://com.example.files/documents/photo");Card c=reference("ref",uri);assertEquals(c.mediaUri(),c.copy().mediaUri());assertTrue(c.matches("screenshot.png"));assertThrows(IllegalArgumentException.class,()->c.setMediaReference("file:///sdcard/photo.png","x"));assertThrows(IllegalArgumentException.class,()->c.setMediaReference("https://example.com/photo.png","x"));Card existing=new Card("ref","https://example.com","Link","Al","Later",0,false,Collections.emptyList());Card merged=CardCodec.merge(Collections.singletonList(existing),Collections.singletonList(c)).get(1);assertNotEquals("ref",merged.id);assertEquals(uri.toString(),merged.mediaUri());}
    @Test public void versionFiveCopiesRemainReadableAfterMigration()throws Exception{Card c=new Card("old","","Old copy","Al","Later",0,false,Collections.emptyList(),"",String.join("",Collections.nCopies(64,"a")),Collections.emptyList(),"","ready");JSONObject json=new JSONObject(CardCodec.encode(Collections.singletonList(c))).put("version",5);JSONObject data=json.getJSONArray("cards").getJSONObject(0);data.remove("mediaUri");data.remove("mediaName");Card old=CardCodec.decode(json.toString()).get(0);assertTrue(old.isImage());assertFalse(old.isReference());assertEquals(c.imageId,old.imageId);}
    @Test public void sharedPhotoSavesTagsUsingReferenceWithoutStoredImageBytes()throws Exception{Uri uri=Uri.parse("content://com.example.files/documents/shared");register(uri,photo());controller=Robolectric.buildActivity(MainActivity.class).setup();MainActivity activity=controller.get();java.lang.reflect.Field scanner=MainActivity.class.getDeclaredField("imageOcr");scanner.setAccessible(true);scanner.set(activity,new ImageOcr(){void read(Bitmap bitmap,java.util.function.BiConsumer<String,Boolean> result){bitmap.recycle();result.accept("Linked screenshot text",true);}});activity.onNewIntent(new Intent(Intent.ACTION_SEND).setType("image/png").putExtra(Intent.EXTRA_STREAM,uri));await(()->{Dialog dialog=ShadowDialog.getLatestDialog();return dialog!=null&&dialog.findViewById(R.id.capture_image)!=null;});Dialog dialog=ShadowDialog.getLatestDialog();ChipGroup group=dialog.findViewById(R.id.capture_intents);for(int i=0;i<group.getChildCount();i++){Chip chip=(Chip)group.getChildAt(i);if(chip.getText().toString().equals("Al"))chip.performClick();}((EditText)dialog.findViewById(R.id.capture_tags)).setText("Alışveriş");dialog.findViewById(R.id.capture_save).performClick();CardStore store=new CardStore(activity.getFilesDir());await(()->{try{store.load();return store.all().size()==1&&store.all().get(0).ocrState.equals("ready");}catch(Exception e){return false;}});assertEquals(1,store.all().size());Card c=store.all().get(0);assertTrue(c.matches("linked screenshot"));assertTrue(c.isReference());assertEquals(uri.toString(),c.mediaUri());assertEquals(Collections.singletonList("Alışveriş"),c.tags);assertFalse(new ImageStore(activity).exists(c.imageId));}
    @Test public void missingOriginalKeepsMetadataAndRelinkTargetsSameRecord()throws Exception{Uri uri=Uri.parse("content://com.example.files/documents/missing");org.robolectric.Shadows.shadowOf(RuntimeEnvironment.getApplication().getContentResolver()).registerInputStreamSupplier(uri,()->{throw new java.io.UncheckedIOException(new FileNotFoundException("Removed file"));});assertFalse(new LocalMedia(RuntimeEnvironment.getApplication()).accessible(uri));Card c=reference("ref",uri);CardStore store=new CardStore(RuntimeEnvironment.getApplication().getFilesDir());store.load();store.save(c);controller=Robolectric.buildActivity(MainActivity.class).setup();MainActivity activity=controller.get();java.lang.reflect.Method relink=MainActivity.class.getDeclaredMethod("relink",Card.class);relink.setAccessible(true);relink.invoke(activity,c);Intent picker=org.robolectric.Shadows.shadowOf(activity).getNextStartedActivity();assertEquals(Intent.ACTION_OPEN_DOCUMENT,picker.getAction());assertTrue((picker.getFlags()&Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)!=0);Uri replacement=Uri.parse("content://com.example.files/documents/replacement");register(replacement,photo());activity.onActivityResult(44,android.app.Activity.RESULT_OK,new Intent().setData(replacement));await(()->{Dialog dialog=ShadowDialog.getLatestDialog();return dialog!=null&&dialog.findViewById(R.id.capture_save)!=null;});ShadowDialog.getLatestDialog().findViewById(R.id.capture_save).performClick();store.load();assertEquals(1,store.all().size());assertEquals("ref",store.all().get(0).id);assertEquals(replacement.toString(),store.all().get(0).mediaUri());assertEquals(c.tags,store.all().get(0).tags);assertEquals(c.note,store.all().get(0).note);}
}
